import { extractApiMessage } from "@/lib/api/errors";
import type { ApiMethod } from "@/types/common.types";

type RequestOptions = {
  method?: ApiMethod;
  body?: BodyInit | FormData | Record<string, unknown> | null;
  headers?: HeadersInit;
  signal?: AbortSignal;
  cache?: RequestCache;
};

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === "object" && !Array.isArray(value) && !(value instanceof FormData) && !(value instanceof URLSearchParams) && !(value instanceof Blob);
}

function toRequestPath(path: string) {
  const normalized = path.startsWith("/") ? path : `/${path}`;

  if (normalized.startsWith("/api/auth/") || normalized.startsWith("/api/proxy/")) {
    return normalized;
  }

  return `/api/proxy${normalized}`;
}

export const APP_SESSION_EXPIRED_EVENT = "fortsolar:session-expired";

export class AppRequestError extends Error {
  status: number;
  payload: unknown;

  constructor(message: string, status: number, payload: unknown) {
    super(message);
    this.name = "AppRequestError";
    this.status = status;
    this.payload = payload;
  }
}

export function isAppSessionExpiredError(error: unknown) {
  return error instanceof AppRequestError && error.status === 401;
}

async function parseResponseBody(response: Response) {
  const contentType = response.headers.get("content-type") ?? "";

  if (contentType.includes("application/json")) {
    return response.json().catch(() => null);
  }

  return response.text().catch(() => null);
}

export async function appRequest<TResponse>(path: string, options: RequestOptions = {}) {
  const headers = new Headers(options.headers);
  const requestPath = toRequestPath(path);
  const requestInit: RequestInit = {
    method: options.method ?? "GET",
    headers,
    signal: options.signal,
    cache: options.cache ?? "no-store",
    credentials: "same-origin",
  };

  if (options.body instanceof FormData || typeof options.body === "string" || options.body instanceof URLSearchParams || options.body instanceof Blob) {
    requestInit.body = options.body;
  } else if (isPlainObject(options.body)) {
    headers.set("Content-Type", "application/json");
    requestInit.body = JSON.stringify(options.body);
  }

  const response = await fetch(requestPath, requestInit);
  const payload = await parseResponseBody(response);

  if (!response.ok || (payload && typeof payload === "object" && "success" in payload && payload.success === false)) {
    const message = extractApiMessage(payload);

    if (
      typeof window !== "undefined" &&
      response.status === 401 &&
      !requestPath.startsWith("/api/auth/")
    ) {
      window.dispatchEvent(
        new CustomEvent(APP_SESSION_EXPIRED_EVENT, {
          detail: {
            message,
            path: requestPath,
            status: response.status,
          },
        }),
      );
    }

    throw new AppRequestError(message, response.status, payload);
  }

  return payload as TResponse;
}

export function appGet<TResponse>(path: string, options: Omit<RequestOptions, "method" | "body"> = {}) {
  return appRequest<TResponse>(path, { ...options, method: "GET" });
}

export function submitAppForm<TResponse>(
  path: string,
  body: RequestOptions["body"],
  options: Omit<RequestOptions, "method" | "body"> & { method?: Exclude<ApiMethod, "GET"> } = {},
) {
  return appRequest<TResponse>(path, {
    ...options,
    method: options.method ?? "POST",
    body,
  });
}
